CREATE TABLE "downloads" ("id" TEXT NOT NULL, "url" TEXT NOT NULL, "final_url" TEXT NULL, "file_name" TEXT NULL, "save_dir" TEXT NOT NULL, "total_bytes" INTEGER NULL, "downloaded_bytes" INTEGER NOT NULL DEFAULT 0, "status" TEXT NOT NULL, "supports_ranges" INTEGER NOT NULL DEFAULT 0 CHECK ("supports_ranges" IN (0, 1)), "resumable" INTEGER NOT NULL DEFAULT 1 CHECK ("resumable" IN (0, 1)), "etag" TEXT NULL, "last_modified" TEXT NULL, "content_type" TEXT NULL, "request_headers" TEXT NOT NULL DEFAULT '{}', "max_connections" INTEGER NOT NULL DEFAULT 8, "source" TEXT NOT NULL DEFAULT 'manual', "error_code" TEXT NULL, "error_message" TEXT NULL, "created_at" INTEGER NOT NULL, "completed_at" INTEGER NULL, PRIMARY KEY ("id"));
CREATE TABLE "segments" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "download_id" TEXT NOT NULL REFERENCES downloads (id) ON DELETE CASCADE, "segment_index" INTEGER NOT NULL, "start_offset" INTEGER NOT NULL, "end_offset" INTEGER NOT NULL, "downloaded_bytes" INTEGER NOT NULL DEFAULT 0, "status" TEXT NOT NULL, UNIQUE ("download_id", "segment_index"));
CREATE TABLE "settings" ("key" TEXT NOT NULL, "value" TEXT NOT NULL, PRIMARY KEY ("key"));
